          "name": "service_point_capacity",
          "description": "每个服务点的服务量必须为2^x - 1，其中x是1到60的整数。",
          "formal": "∀i, a_i = 2^{x_i} - 1, 1 ≤ x_i ≤ 60",
          "source_sections": ["description"]
        },
