          "name": "modular_output",
          "description": "由于答案可能很大，输出方案数模1000000007。",
          "source_sections": ["description"]
        }
      ]
    },
    "objective": {
      "type": "count",
      "description": "统计所有满足需求码C且服务点数最少的服务点序列的个数，模1000000007。",
      "modulus": 1000000007,
      "requires_solution": true
    },
