  "applied_helpers": [
    {
      "id": "counting_unit_definition",
      "selection_reason": "为将原题从构造转为计数，必须明确定义计数对象和去重规则。",
      "affected_axes": ["C", "O", "V"],
      "schema_changes": [
        "core_constraints中增加计数目标和去重规则约束",
        "objective类型改为count并指定模数",
        "invariant中纳入计数单元划分的描述"
      ],
      "innovation_reason": "从单一构造变为统计所有最优构造，提升了问题的组合分析要求。",
      "difficulty_reason": "增加了处理等价类和模数下的计数正确性，提高了难度。"
    },
    {
      "id": "state_factorization",
      "selection_reason": "计数需要分解解空间为可汇总的单元，不能保持原贪心状态结构。",
      "affected_axes": ["C", "V"],
      "schema_changes": [
        "core_constraints中隐含需求码的位段分解作为计数基础",
        "invariant中引入基于位段的状态分解和DP不变量"
      ],
      "innovation_reason": "迫使解法重新设计状态结构，从位段角度组合计数，而非在原解上粘贴。",
      "difficulty_reason": "要求建立新的状态转移模型，增加算法设计深度。"
    },
    {
      "id": "counting_obligation_lock",
      "selection_reason": "确保计数是主要义务，防止原优化目标残留。",
      "affected_axes": ["C", "O"],
      "schema_changes": [
        "objective不再是最小化n，而是计数",
        "核心约束中最小长度作为解必须满足的性质而非优化目标"
      ],
      "innovation_reason": "替换原题的核心任务，改变了解题的主导逻辑。",
      "difficulty_reason": "算法必须同时考虑最小长度判定和计数，且无法分步投机取巧。"
    }
  ],
  "shared_core_summary": "",
