user_prompt:
请审查该规划是否兑现规则专属合同。
要求：
- `message` 直接概括结论，不要泛泛而谈。
- `errors` 只写真正构成拒绝的规则专属问题；通过时返回空数组。
- `evidence` 必须引用给定 payload、schema 或规则声明中的具体内容。
- 如果规则声明了 `helpers`，要逐条核对 helper 是否全部出现，以及每个 helper 是否兑现了自己的目标变化轴、落点和 redlines。
- 如果不能确认已经兑现规则专属合同，返回 `fail`。

{
  "review_type": "rule_plan_validation",
  "mode": "single_seed_extension",
  "review_role": "你扮演一名计数规划审查官，重点确认规划是否真正把目标升级为对象明确的计数任务。",
  "review_brief": "确认规划是否定义了计数对象、去重口径、有限性来源，以及需要时的取模约定。",
  "rule_under_review": {
    "id": "existence_to_counting",
    "family": "objective_upgrade",
    "summary": "把存在性或单一最优值问题改成一个对象明确、去重规则明确的计数题。",
    "audit_tags": [
      "single_seed",
      "counting",
      "deduplication"
    ],
    "required_axis_changes": {
      "must_change": [
        "O",
        "C",
        "V"
      ]
    },
    "core_transformation": {
      "primary_operator": "existence_to_counting",
      "target_shift": "从存在性或最优值改成计数",
      "new_obligation": "定义清楚计数对象、有限性和去重规则"
    },
    "helpers": [
      {
        "id": "counting_unit_definition",
        "summary": "明确计数对象、等价关系与不同答案口径。",
        "must_realize_in": [
          "core_constraints",
          "objective",
          "invariant"
        ],
        "target_axes": [
          "C",
          "O",
          "V"
        ],
        "innovation_role": "把原题答案换成对象明确的计数结果。",
        "difficulty_role": "要求解法处理等价类和有限性证明。",
        "prompt_guidance": [
          "把计数对象直接写进目标定义。",
          "把去重口径写进约束或不变量。"
        ],
        "redlines": [
          "不能只补一个模数。",
          "不能不定义什么算不同答案。"
        ]
      },
      {
        "id": "state_factorization",
        "summary": "把解空间拆成可汇总的计数单元。",
        "must_realize_in": [
          "core_constraints",
          "invariant"
        ],
        "target_axes": [
          "C",
          "V"
        ],
        "innovation_role": "让计数从主状态组织方式中自然长出来。",
        "difficulty_role": "要求解法在分解与汇总层面重建主状态。",
        "prompt_guidance": [
          "让核心约束说明如何拆成计数单元。",
          "让不变量解释单元之间如何避免重复。"
        ],
        "redlines": [
          "不能保持原状态结构不动。",
          "不能把计数只当成结果后处理。"
        ]
      },
      {
        "id": "counting_obligation_lock",
        "summary": "把计数责任锁进主求解目标而不是附带统计。",
        "must_realize_in": [
          "core_constraints",
          "objective"
        ],
        "target_axes": [
          "C",
          "O"
        ],
        "innovation_role": "把原题主目标替换成新的计数义务。",
        "difficulty_role": "要求算法同时承担计数正确性和去重正确性。",
        "prompt_guidance": [
          "让目标定义主导状态转移。",
          "不要保留原判定主目标再顺手计数。"
