要求：
- 只能判断该规则是否适合进入下一阶段规划。
- `selection_reason` 直接写结论依据，不要泛泛而谈。
- `evidence` 必须引用 schema、原题摘要或规则声明中的具体证据。
- `score` 取 0 到 1，表示进入后续规划的把握度；拒绝时可以是 0 到 0.49。
- `risk_tags` 只保留高价值风险标签，例如 `low_novelty`、`shared_core_risk`、`semantic_mismatch`。
- 如果 schema 信息不足以判断，返回 `schema_insufficient`。
- 如果不确定，返回 `ineligible`。

{
  "review_type": "eligibility",
  "mode": "single_seed_extension",
  "review_role": "你扮演一名全局覆盖审查官，重点判断局部路径、区间或子结构是否能扩成覆盖、割或支配问题。",
  "rule_under_review": {
    "id": "local_path_to_global_cover",
    "family": "global_cover",
    "audit_tags": [
      "single_seed",
      "cover",
      "cut_or_dominance"
    ],
    "handler": "local_path_to_global_cover",
    "enabled": true,
    "summary": "把单路径、单区间或单子树性质扩展为覆盖、割、支配或多对象联动约束题。",
    "eligibility": {
      "required_seed_properties": [
        "原题核心对象具有路径、区间、子树、集合等局部结构",
        "多个局部对象之间可以自然形成覆盖或割关系"
      ],
      "forbidden_seed_properties": [
        "不存在可组合的局部对象族",
        "覆盖关系只能靠无关附加限制产生"
      ]
    },
    "required_axis_changes": {
      "must_change": [
        "C",
        "O",
        "V"
      ]
    },
    "core_transformation": {
      "primary_operator": "local_path_to_global_cover",
      "target_shift": "从单个局部对象求解改成全局覆盖或切断",
      "new_obligation": "定义对象族、覆盖口径和全局可验证条件"
    },
    "helpers": [
      {
        "id": "object_family_expansion",
        "summary": "把单个路径、区间或子结构扩成需要同时处理的对象族。",
        "must_realize_in": [
          "core_constraints",
          "objective"
        ],
        "target_axes": [
          "C",
          "O"
        ],
        "innovation_role": "让问题从局部求解升级为全局对象族管理。",
        "difficulty_role": "要求算法处理多个对象之间的交叠与选择。",
        "prompt_guidance": [
          "目标必须涉及覆盖、割、支配或多对象满足。",
          "核心约束要定义对象族如何产生。"
        ],
        "redlines": [
          "不能只是重复处理多个独立对象。",
          "不能只把单对象答案输出多次。"
        ]
      },
      {
        "id": "cover_cut_consistency",
        "summary": "定义覆盖、割或支配关系的一致性约束。",
        "must_realize_in": [
          "core_constraints",
          "invariant"
        ],
        "target_axes": [
          "C",
          "V"
        ],
        "innovation_role": "让多个局部对象通过同一个全局选择相互制约。",
        "difficulty_role": "要求证明全局选择对所有对象同时成立。",
        "prompt_guidance": [
          "覆盖或割关系必须能从原结构验证。",
          "不变量要说明全局选择如何支配对象族。"
        ],
        "redlines": [
          "不能只定义互不关联的局部条件。",
          "不能让全局选择脱离原结构。"
        ]
      },
      {
        "id": "global_certificate_or_value",
        "summary": "把输出责任改成全局覆盖值、最小割或可验证方案。",
        "must_realize_in": [
          "objective",
          "invariant"
        ],
        "target_axes": [
          "O",
          "V"
        ],
        "innovation_role": "让答案承载全局对象族的统一证明。",
        "difficulty_role": "要求解法证明最小性、最大性或覆盖完备性。",
        "prompt_guidance": [
          "目标要写清输出值或方案如何验证全局性质。",
          "不变量要支撑全局完备性或下界。"
        ],
        "redlines": [
          "不能只输出任意局部对象。",
          "不能省略全局验证口径。"
        ]
      }
    ],
    "validation_contract": {
      "hard_checks": [
        "必须从局部对象族形成全局覆盖或割语义",
        "全局选择必须同时影响多个对象",
        "必须有全局验证或最优性责任"
      ]
    },
    "examples": {
      "positive": "把求一条路径的性质改成选择最少点覆盖所有给定路径。",
      "negative": "分别对每条路径运行原算法后输出结果列表。"
    },
    "failure_templates": {
      "not_applicable": "这道种子题没有适合扩成覆盖或割的局部对象族。",
      "difference_insufficient": "全局覆盖语义没有进入主约束，只是重复局部问题。"
    },
    "planner_output_contract": {
      "required_fields": [
        "eligibility_reason",
        "core_transformation_summary",
        "difference_plan",
        "new_schema",
        "algorithmic_delta_claim",
        "anti_shallow_rationale",
        "applied_helpers"
      ]
    }
  },
