    "seed_schema": {
      "problem_id": "taco_codeforces_43dc8145a4f7",
      "source": "codeforces",
      "input_structure": {
        "type": "composite",
        "length": {
          "min": null,
          "max": null
        },
        "value_range": {
          "min": null,
          "max": null
        },
        "properties": {},
        "components": [
          {
            "role": "parameters",
            "role_description": "number of rows and number of groups",
            "type": "tuple",
            "length": {
              "min": 2,
              "max": 2
            },
            "value_range": {
              "min": null,
              "max": null
            },
            "properties": {}
          },
          {
            "role": "group_sizes",
            "role_description": "number of soldiers in each group",
            "type": "array",
            "length": {
              "min": 1,
              "max": 100
            },
            "value_range": {
              "min": 1,
              "max": 10000
            },
            "properties": {}
          }
        ]
      },
      "core_constraints": {
        "constraints": [
          {
            "name": "no_adjacent_different_groups",
            "description": "No two soldiers from different groups may sit on neighboring seats, where neighboring seats are defined as pairs {1,2}, {3,4}, {4,5}, {5,6}, {7,8} in the same row.",
            "formal": "∀ row r, ∀ neighbor pair (s1, s2) ∈ {{1,2},{3,4},{4,5},{5,6},{7,8}}, if seat s1 and s2 are occupied then group(s1) == group(s2).",
            "source_sections": [
              "description"
            ]
          }
        ]
      },
      "objective": {
        "type": "decision",
        "description": "Determine whether there exists an arrangement of soldiers meeting the given condition",
        "target": "",
        "requires_solution": false
      },
      "invariant": {
        "invariants": [
          {
            "name": "seat_connectivity_partition",
            "description": "Each row of 8 seats is divided by adjacency into three connected components: two of size 2 (left and right) and one of size 4 (middle). Within each component all seats must be assigned to the same group.",
            "properties": {
              "partition_capacities": [
                2,
                4,
                2
              ],
              "same_group_per_component": true
            },
            "evidence_source": "statement"
          },
          {
            "name": "maximal_four_block_extraction",
            "description": "For each group, as many complete blocks of 4 soldiers as possible are greedily assigned to free size‑4 components, while size‑4 components remain. This transformation preserves feasibility: if any valid arrangement exists, one exists that respects this greedy assignment.",
            "properties": {
              "block_size": 4,
              "target_component_capacity": 4,
              "preserves_feasibility": true
            },
            "evidence_source": "solution_code"
          },
          {
            "name": "demand_reduction_with_four_components",
            "description": "After extracting all possible size‑4 blocks, the residual demand of groups can be expressed in terms of required size‑2 components (ceil(remaining/2) for each group). Any still unused size‑4 component can be used to satisfy parts of this demand, reducing the number of required size‑2 components by at most 2, depending on the exact composition of 1s, 2s, and 3s. The algorithm greedily applies these substitutions and checks whether the final required number of size‑2 components does not exceed 2n.",
            "properties": {
              "size2_demand_unit": "ceil(remaining/2)",
              "max_reduction_per_four_component": 2
            },
            "evidence_source": "solution_code"
          }
        ]
      }
    }
  },
  "original_problem_references": [
    {}
  ],
