    "allow_helper_moves": true
  },
  "global_redlines": [
    "只换故事背景",
    "纯改输入输出格式",
    "只改参数范围，状态结构不变",
    "跟原核心规律无关的额外约束",
    "把两道子任务前后串起来"
  ]
}

