messages.content:
请在当前规则集中选择最适合当前 schema 的规则。
要求：
- 目标是在保证可落地的前提下，让生成题的创新度和难度尽可能高。
- 如果某条规则只会导致浅改、换皮、后处理增强或伪融合，不要选择它。
- `selection_reason` 要直接说明为什么它优于其余规则。
- 优先返回 `ranked_rule_ids`，按推荐尝试顺序排列前 2 到 3 条规则；`selected_rule_id` 保留为第一推荐项。
- `innovation_reason` 要说明它会把哪些核心义务拉离原题。
- `difficulty_reason` 要说明它会在哪个主求解责任上抬高难度。
- `risk_reason` 要说明主要风险；如果风险可控，也要明确写出来。
- 如果提供了 `revision_context`，要优先修复其中涉及规则选择、结构差异和反换皮风险的问题，并保留 `strengths_to_keep`。
- 若 `revision_context` 包含 `revision_history` 或 `revision_summary`，必须综合此前所有轮次的有用信息，不要只依据最近一轮的修订建议。
- 如果没有规则满足条件，返回失败状态，不要勉强挑选。

{
  "mode": "single_seed_extension",
  "available_rules": [
    {
      "id": "construct_or_obstruction",
      "family": "certificate_output",
      "audit_tags": [
        "single_seed",
        "certificate",
        "failure_semantics"
      ],
      "handler": "construct_or_obstruction",
      "enabled": true,
      "summary": "要求输出一个合法方案；如果做不到，就输出一个能直接检查的局部冲突证据。",
      "eligibility": {
        "required_seed_properties": [
          "做不到的原因可以用局部证据表示",
          "冲突证据可以从输出直接检查"
        ],
        "forbidden_seed_properties": [
          "只能给出抽象解释，没法给出明确证据"
        ]
      },
      "required_axis_changes": {
        "must_change": [
          "C",
          "O",
          "V"
        ]
      },
      "core_transformation": {
        "primary_operator": "construct_or_obstruction",
        "target_shift": "从判定或求值改成给方案或给冲突证据",
        "new_obligation": "输出合法方案，或者输出局部冲突证据"
      },
      "helpers": [
        {
          "id": "local_certificate_design",
          "summary": "把无解原因压成可局部检查的证据对象。",
          "must_realize_in": [
            "core_constraints",
            "objective",
            "invariant"
          ],
          "target_axes": [
            "C",
            "O",
            "V"
          ],
          "innovation_role": "让失败语义从解释变成输出对象。",
          "difficulty_role": "要求解法同时构造成功分支和失败证据分支。",
          "prompt_guidance": [
            "让失败输出拥有明确结构。",
            "让证据可以在局部规则下直接检查。"
          ],
          "redlines": [
            "不能只写无解原因说明。",
            "不能让失败输出退化成自然语言解释。"
          ]
        },
        {
          "id": "failure_branch_symmetry",
          "summary": "让成功分支与失败分支都承担正式输出责任。",
          "must_realize_in": [
            "core_constraints",
            "objective"
          ],
          "target_axes": [
            "C",
            "O"
          ],
          "innovation_role": "把单目标输出改成双分支输出合同。",
          "difficulty_role": "要求算法统一处理两类输出语义。",
          "prompt_guidance": [
            "让两条分支共享输入语义但承担不同输出对象。",
            "让失败分支不能靠特判绕开主结构。"
          ],
          "redlines": [
            "不能让失败分支成为附属备注。",
            "不能只定义成功分支。"
          ]
        },
        {
          "id": "obstruction_embedding",
          "summary": "让冲突证据直接来自主约束中的不可兼容关系。",
          "must_realize_in": [
            "core_constraints",
            "invariant"
          ],
          "target_axes": [
            "C",
            "V"
          ],
          "innovation_role": "让失败证据嵌入主约束内部，而不是依赖额外情形放大。",
          "difficulty_role": "要求解法在同一状态信息里同时解释成功构造与失败证据。",
          "prompt_guidance": [
            "让主约束天然定义证据结构。",
            "让成功分支与失败分支共享同一状态信息来源。"
          ],
          "redlines": [
            "不能依赖边界特判才构造证据。",
            "不能让证据脱离主求解过程。"
          ]
        }
      ],
      "validation_contract": {
        "hard_checks": [
          "冲突证据必须能局部检查",
          "不能退化成一段解释"
        ]
      },
      "examples": {
        "positive": "输出一个最小冲突集合，作为做不到的证据。",
        "negative": "只在说明里解释为什么做不到。"
      },
      "failure_templates": {
        "not_applicable": "这道种子题做不到的原因没法稳定地写成局部证据。",
        "difference_insufficient": "方案或冲突证据没有带来新的校验责任。"
      },
      "planner_output_contract": {
        "required_fields": [
          "eligibility_reason",
          "core_transformation_summary",
          "difference_plan",
          "new_schema",
          "algorithmic_delta_claim",
          "anti_shallow_rationale",
          "applied_helpers"
        ]
      }
    },
    {
      "id": "existence_to_counting",
      "family": "objective_upgrade",
      "audit_tags": [
        "single_seed",
        "counting",
        "deduplication"
      ],
      "handler": "existence_to_counting",
      "enabled": true,
      "summary": "把存在性或单一最优值问题改成一个对象明确、去重规则明确的计数题。",
      "eligibility": {
        "required_seed_properties": [
          "解空间有限",
          "不同解之间的等价关系能说清楚",
          "可以按某种单元拆分并汇总"
        ],
        "forbidden_seed_properties": [
          "解空间天然无限",
          "去重规则说不清楚"
        ]
      },
      "required_axis_changes": {
        "must_change": [
          "O",
          "C",
          "V"
        ]
      },
      "core_transformation": {
        "primary_operator": "existence_to_counting",
        "target_shift": "从存在性或最优值改成计数",
        "new_obligation": "定义清楚计数对象、有限性和去重规则"
      },
      "helpers": [
        {
          "id": "counting_unit_definition",
          "summary": "明确计数对象、等价关系与不同答案口径。",
          "must_realize_in": [
            "core_constraints",
            "objective",
            "invariant"
          ],
          "target_axes": [
            "C",
            "O",
            "V"
          ],
          "innovation_role": "把原题答案换成对象明确的计数结果。",
          "difficulty_role": "要求解法处理等价类和有限性证明。",
          "prompt_guidance": [
            "把计数对象直接写进目标定义。",
            "把去重口径写进约束或不变量。"
          ],
          "redlines": [
            "不能只补一个模数。",
            "不能不定义什么算不同答案。"
          ]
        },
        {
          "id": "state_factorization",
          "summary": "把解空间拆成可汇总的计数单元。",
          "must_realize_in": [
            "core_constraints",
            "invariant"
          ],
          "target_axes": [
            "C",
            "V"
          ],
          "innovation_role": "让计数从主状态组织方式中自然长出来。",
          "difficulty_role": "要求解法在分解与汇总层面重建主状态。",
          "prompt_guidance": [
            "让核心约束说明如何拆成计数单元。",
            "让不变量解释单元之间如何避免重复。"
          ],
          "redlines": [
            "不能保持原状态结构不动。",
            "不能把计数只当成结果后处理。"
          ]
        },
        {
          "id": "counting_obligation_lock",
          "summary": "把计数责任锁进主求解目标而不是附带统计。",
          "must_realize_in": [
            "core_constraints",
            "objective"
          ],
          "target_axes": [
            "C",
            "O"
          ],
          "innovation_role": "把原题主目标替换成新的计数义务。",
          "difficulty_role": "要求算法同时承担计数正确性和去重正确性。",
          "prompt_guidance": [
            "让目标定义主导状态转移。",
            "不要保留原判定主目标再顺手计数。"
          ],
          "redlines": [
            "不能继续由原题判定过程主导。",
            "不能把计数目标放进备注。"
          ]
        }
      ],
      "validation_contract": {
        "hard_checks": [
          "必须说明什么样的解算不同",
          "必须说明为什么可数，或者说明取模方式",
          "必须说明按什么单元拆分和汇总"
        ]
      },
      "examples": {
        "positive": "统计所有满足约束的最优构造数，并定义去重与取模。",
        "negative": "把是否存在改成计数，但状态结构和计数对象都没重新定义。"
      },
      "failure_templates": {
        "not_applicable": "这道种子题没有稳定的有限解空间，或者去重规则说不清楚，不适合改成计数题。",
        "difference_insufficient": "改成计数之后没有带来明显的新责任，看起来只是换了答案形式。"
      },
      "planner_output_contract": {
        "required_fields": [
          "eligibility_reason",
          "core_transformation_summary",
          "difference_plan",
          "new_schema",
          "algorithmic_delta_claim",
          "anti_shallow_rationale",
          "applied_helpers"
        ]
      }
    },
    {
      "id": "single_objective_to_tradeoff_frontier",
      "family": "multi_objective_tradeoff",
      "audit_tags": [
        "single_seed",
        "tradeoff",
        "pareto_frontier"
      ],
      "handler": "single_objective_to_tradeoff_frontier",
      "enabled": true,
      "summary": "把单目标最优题扩展为预算、收益、风险等多指标权衡或前沿查询题。",
      "eligibility": {
        "required_seed_properties": [
          "原题目标附近存在自然的第二评价指标",
          "两个指标之间存在真实冲突，不能同时独立最优"
        ],
        "forbidden_seed_properties": [
          "第二指标只是原目标的同义改写",
          "权衡关系可以由原答案直接后处理得到"
        ]
      },
      "required_axis_changes": {
        "must_change": [
          "C",
          "O",
          "V"
        ]
      },
      "core_transformation": {
        "primary_operator": "single_objective_to_tradeoff_frontier",
        "target_shift": "从单目标最优改成双指标权衡",
        "new_obligation": "定义主指标、约束指标和前沿或最优折中口径"
      },
      "helpers": [
        {
          "id": "secondary_metric_materialization",
          "summary": "引入与原目标冲突的第二指标。",
          "must_realize_in": [
            "core_constraints",
            "objective"
          ],
          "target_axes": [
            "C",
            "O"
          ],
          "innovation_role": "让目标空间从一维扩展到真实权衡。",
          "difficulty_role": "要求算法同时跟踪两个评价维度。",
          "prompt_guidance": [
            "第二指标必须来自原题对象的自然属性。",
            "目标要写清主指标与约束指标的关系。"
          ],
          "redlines": [
            "不能把第二指标写成原指标的别名。",
            "不能只增加一个无影响的附加输出。"
          ]
        },
        {
          "id": "frontier_dominance_rule",
          "summary": "定义支配关系、预算约束或前沿输出口径。",
          "must_realize_in": [
            "objective",
            "invariant"
          ],
          "target_axes": [
            "O",
            "V"
          ],
          "innovation_role": "把答案从单个最优值变成可比较的前沿语义。",
          "difficulty_role": "要求解法维护不可支配状态或折中证明。",
          "prompt_guidance": [
            "说明什么方案被另一个方案支配。",
            "不变量要支撑前沿剪枝或预算转移。"
          ],
          "redlines": [
            "不能只输出两个独立最优值。",
            "不能缺少比较口径。"
          ]
        },
        {
          "id": "coupled_state_expansion",
          "summary": "让核心状态同时承载两个指标的耦合变化。",
          "must_realize_in": [
            "core_constraints",
            "invariant"
          ],
          "target_axes": [
            "C",
            "V"
          ],
          "innovation_role": "阻止多目标退化成两个独立子题。",
          "difficulty_role": "要求证明状态压缩不会丢掉折中信息。",
          "prompt_guidance": [
            "状态或约束必须体现指标之间的相互影响。",
            "不变量要解释为何不能先优化一个再优化另一个。"
          ],
          "redlines": [
            "不能拆成先求目标 A 再求目标 B。",
            "不能让第二指标只在排序时出现。"
          ]
        }
      ],
      "validation_contract": {
        "hard_checks": [
          "第二指标必须与原目标真实冲突",
          "必须定义支配或预算口径",
          "不能退化成两个独立最优值"
