          "description": "After modification, the student positions must guarantee capture: for every leaf classroom l, there exists at least one student i such that the shortest-path distance from i to l is less than or equal to the distance from room 1 to l.",
          "formal": "∀ leaf l ∈ L, ∃ i: d(x'_i, l) ≤ d(1, l)",
          "source_sections": [
            "derived"
          ]
        },
        {
          "name": "allowed_modification",
          "description": "For each student, you may choose to change its initial room to any other room. The cost of changing a student from room a to room b is the shortest-path distance d(a,b) along the tree. Multiple students can be moved to the same room.",
          "formal": "ops = {move(i, v) : i ∈ [1..k], v ∈ V, cost = d(x_i, v)}",
          "source_sections": [
            "description"
          ]
        },
        {
          "name": "minimize_total_cost",
          "description": "Select a set of modifications minimizing the total cost sum_{i} cost_i such that the resulting positions x'_1,...,x'_k satisfy the target capture condition.",
          "formal": "",
          "source_sections": [
            "description",
            "output"
          ]
        }
      ]
    },
    "objective": {
      "type": "minimize_value",
      "description": "Minimize the total movement cost (sum of shortest-path distances moved) required to reposition the students so that they can guarantee capturing the principal.",
