      "requires_solution": false
    },
    "invariant": {
      "invariants": [
        {
          "name": "leaf_coverage_after_modification",
          "description": "After applying the chosen modifications, for every leaf classroom l, there is at least one student i with d(x'_i, l) ≤ d(1, l).",
          "properties": {},
          "evidence_source": "derived"
        },
        {
          "name": "cost_lower_bound",
          "description": "The total movement cost cannot be less than the minimum sum of distances from initial positions to a set of target rooms that satisfies the leaf coverage condition.",
          "properties": {},
          "evidence_source": "solution_code"
        },
        {
          "name": "no_unnecessary_moves",
          "description": "Any optimal set of modifications uses only movements that are strictly necessary to achieve the leaf coverage; moving a student without changing the set of covered leaves would increase cost without benefit.",
          "properties": {},
          "evidence_source": "proof"
        }
      ]
    },
    "difficulty": "medium"
  },
  "algorithmic_delta_claim": {
    "seed_solver_core": "多源 BFS 计算每个房间到朋友和 Vlad 的距离，通过比较每个叶子上的距离判断哪些朋友集合能保证抓捕。",
    "reusable_subroutines": "树上的 BFS/最短距离计算、叶子节点识别。",
    "new_solver_core": "将问题建模为：给定初始位置，需为每个学生选择一个新的目标房间，使得每片叶子被至少一个学生“控制”（距离不大于校长距离），最小化总移动距离。这可通过枚举叶子的控制候选集、二分图匹配或动态规划求解，核心是证明最优解中目标房间仅需落在某些特定集合内。",
    "new_proof_obligation": "1. 证明最优修改后的学生位置一定可以限制在跨越每个叶子的“控制子图”中；2. 证明总代价最小的分配等价于一个加权集合覆盖的最优解，且可以通过多项式时间算法得到；3. 证明贪心或 DP 策略不会遗漏更小代价方案。",
    "why_direct_reuse_fails": "原算法仅做布尔判定，无法处理允许位置变动并最小化代价的优化问题。必须引入全新的优化维度，并设计算法在改动空间中搜索最优解，这完全改变了问题的求解方向。"
  },
  "anti_shallow_rationale": "非简单换皮：核心约束从静态判定转为动态编辑下的目标达成，输出从最小子集大小变为最小修改代价，算法从判定转为优化，引入编辑操作和覆盖条件，要求证明最小性，使得求解本质改变。场景映射仅提供叙事，结构创新源于逆问题翻转。",
  "applied_helpers": [
