            "min": 1,
            "max": 100000000000000
          },
          "properties": {}
        },
        {
          "role": "matrix",
          "role_description": "n x n matrix of integers, each row is rearrangable",
          "type": "matrix",
          "length": {
            "min": 1,
            "max": 1000000
          },
          "value_range": {
