            "max": 100000000000000
          },
          "properties": {}
        },
        {
          "role": "matrix",
          "role_description": "n x n matrix of integers, each row is rearrangable",
          "type": "matrix",
          "length": {
            "min": 1,
            "max": 1000000
          },
          "value_range": {
            "min": 1,
            "max": 1000000000
          },
          "properties": {
            "ordered": true
          }
        },
        {
          "role": "modulus",
          "role_description": "modulus M for output modulo",
          "type": "integer",
          "length": {
            "min": null,
            "max": null
          },
          "value_range": {
            "min": 2,
            "max": 1000000000
          },
          "properties": {}
        }
      ]
    },
    "core_constraints": {
      "constraints": [
        {
          "name": "median_tuple_counting_definition",
          "description": "计数对象为每行中位数构成的 n 元组 (m_1,...,m_n)。两个解被视为不同当且仅当存在某行 i 使得 m_i 不同。",
          "formal": "A solution is an n-tuple (m_1,...,m_n) such that for each row i, m_i is a legal median of that row (see legal_median). Two tuples are distinct if they differ in at least one coordinate.",
          "source_sections": [
            "description"
          ]
        },
        {
          "name": "legal_median",
          "description": "对于第 i 行，称元素 x 是合法的中位数，当且仅当存在一种行内排列使得排序后中间位置（mid = (n+1)/2，1-indexed）恰为 x，即该行有至少 mid-1 个不大于 x 的元素和至少 n-mid 个不小于 x 的元素。",
          "formal": "In row i, an element x is a legal median iff #{elements in row i ≤ x} ≥ mid and #{elements in row i ≥ x} ≥ n - mid + 1, where mid = (n+1)/2.",
          "source_sections": [
            "description"
          ]
        },
        {
          "name": "cost_constraint",
          "description": "中位数元组必须满足总代价 ∑_{i=1}^{n} m_i ≤ k。",
          "formal": "∑_{i=1}^{n} m_i ≤ k",
          "source_sections": [
            "input"
          ]
        },
        {
          "name": "optimal_goodness_definition",
          "description": "定义最优 goodness G 为在满足合法中位数和总代价不可超过 k 的条件下，所有中位数元组能达到的最大 min_i m_i 值。题目所求计数基于该 G。",
          "formal": "Let T be the set of all legal median tuples satisfying sum ≤ k. Then G = max_{(m_1,...,m_n)∈T} min_i m_i.",
          "source_sections": [
            "description"
          ]
        },
        {
          "name": "target_counting_condition",
          "description": "要求计数的中位数元组需要满足 min_i m_i = G，即最小中位数恰好等于最优值。",
          "formal": "Count tuples in T with min_i m_i = G.",
          "source_sections": [
            "description"
          ]
        },
        {
          "name": "output_modulo",
          "description": "最终计数结果对模数 M 取模后输出。",
          "formal": "Output count mod M.",
          "source_sections": [
            "description"
          ]
        }
      ]
    },
    "objective": {
      "type": "count_solutions",
      "description": "计算在给定矩阵和成本上限 k 下，所有满足合法中位数定义且总代价不超过 k，并使得各行的中位数的最小值恰好等于最大可能值 G 的不同中位数元组的个数，将结果对 M 取模后输出。",
      "target": "median_tuple_count",
      "requires_solution": false
    },
    "invariant": {
      "invariants": [
        {
          "name": "finite_exhaustible_search_space",
          "description": "所有合法中位数元组构成有限集合，其规模被矩阵元素总个数限制，因此可数且去重规则（元组相等）简单明确。",
          "properties": {},
          "evidence_source": "problem_description"
        },
        {
          "name": "state_factorization_for_dp",
          "description": "按行顺序构造中位数元组时，下一行的中位数选择仅依赖于当前已选行的总代价、当前已达的最小值、以及是否出现了等于 G 的行，这些状态足够汇总以进行无重复计数。",
          "properties": {},
          "evidence_source": "solution_code"
        },
        {
          "name": "optimality_monotonicity",
          "description": "计算 G 的过程利用单调性：若存在元组使得 min_i m_i ≥ x，则该性质对任何 y ≤ x 也成立，且二分搜索下界正确。",
          "properties": {},
          "evidence_source": "solution_code"
        },
        {
          "name": "dp_correctness_and_deduplication",
          "description": "DP 状态转移保证每个合法中位数元组被恰好一次计数，利用状态的无后效性和中位数合法性检查的一致性，不因行处理顺序不同而重复。",
          "properties": {},
          "evidence_source": "solution_code"
        }
      ]
    },
    "difficulty": "hard"
  },
  "algorithmic_delta_claim": {
    "seed_solver_core": "二分搜索最优 goodness G，对每个候选 G 通过贪心构造检查可行性：每行选择一个 ≥G 的元素作为中位数，且总代价尽量小，使用双指针确定各行的最小贡献。",
    "reusable_subroutines": "用于判定某个 G 是否可行的贪心可行性检查子过程（可复用以计算最优 G），以及各行的元素预排序和前缀数据结构。",
    "new_solver_core": "在确定 G 后，设计计数 DP，定义状态为 (行索引，当前总代价，是否已有行中位数等于 G)，转移时枚举当前行所有合法中位数候选并对代价和最小值标记进行更新，利用离散化代价或按行滚动的技巧处理大 k，并对 M 取模。",
    "new_proof_obligation": "证明计数 DP 的状态定义完备且无后效；证明合法中位数定义与“存在排列使得 x 为中位数”等价；证明去重规则（元组相等）与 DP 的枚举顺序无冲突；证明取模操作不破坏计数正确性。",
    "why_direct_reuse_fails": "原判断器只能输出布尔值，没有提供计数所需的精细状态空间，直接复用无法得到不同解的数量，且 DP 需要重新设计状态汇总和去重机制，不是简单加一个计数器。"
  },
  "anti_shallow_rationale": "并非仅将原题答案从最大化最小值换成计数，而是重构了核心约束（明确定义计数对象、合法中位数、去重规则），并迫使解法从贪心判定升级为组合计数 DP，状态结构和不变量完全更新，带来了新的正确性证明义务和算法难度。",
  "applied_helpers": [
    {
      "id": "counting_unit_definition",
      "selection_reason": "必须明确计数对象和去重规则，是 existence_to_counting 的核心义务。",
      "affected_axes": [
        "C",
        "O",
        "V"
      ],
      "schema_changes": [
        "在 core_constraints 中添加 median_tuple_counting_definition 和 legal_median 约束，定义中位数元组为计数对象并指定等价关系。",
        "在 objective 中将目标从最大化值改为计数该元组数量。",
        "在 invariant 中添加有限集和去重完备性不变量。"
      ],
      "innovation_reason": "将原有的模糊‘解’具体化为中位数元组，并严格定义不同解，使问题从存在性彻底转向组合计数。",
      "difficulty_reason": "增加了对合法中位数的组合定义和去重逻辑，要求解答方从底层理解等价类划分。"
    },
    {
      "id": "state_factorization",
      "selection_reason": "计数问题必须将解空间分解为可汇总的计数单元，符合规则要求的 state factorization。",
      "affected_axes": [
        "C",
        "V"
      ],
      "schema_changes": [
        "在 core_constraints 中通过 target_counting_condition 和 optimal_goodness_definition 隐含将解空间按 G 划分。",
        "在 invariant 中添加 state_factorization_for_dp 不变量，明确按行处理，状态仅包含代价和最小中位数标记，可无重复汇总。"
      ],
      "innovation_reason": "原题解空间散乱，现在通过定义清晰的状态抽象将计数分解为可递推的单元，使解法设计自然导向 DP。",
      "difficulty_reason": "要求解法设计合适的状态表示来遍历大量候选，并证明状态数有限且不重复，增加了算法设计复杂度。"
    },
    {
      "id": "counting_obligation_lock",
      "selection_reason": "确保计数义务嵌入核心目标，而非附加任务。",
      "affected_axes": [
        "C",
        "O"
      ],
      "schema_changes": [
        "objective 完全改为计数输出，删除原最大化目标。",
        "core_constraints 中绑定 optimal_goodness_definition 和 target_counting_condition，使得求 G 只是计数的前置定义，不单独作为输出目标。"
      ],
      "innovation_reason": "将计数义务提升为题目唯一输出，迫使解题完全围绕计数逻辑重构，而不是在原判定基础上简单累加。",
