          }
        }
      ]
    },
    "core_constraints": {
      "constraints": [
        {
          "name": "valid_permuted_rows",
          "description": "输出的每一行必须是输入对应行的一个排列。",
          "formal": "对于每个 i，输出行 i 是输入行 i 的一个重排。",
          "source_sections": ["description"]
        },
        {
          "name": "cost_upper_bound",
          "description": "重排后所有行中位数的总和不超过 k。中位数定义为该行元素按升序排列后的第 m = ⌈n/2⌉ 个元素。",
          "formal": "∑_{i=1}^{n} median(row_i) ≤ k",
          "source_sections": ["description", "input"]
        },
        {
          "name": "canonical_ordering",
          "description": "规范解要求每行内的元素以升序排列输出。整个矩阵的字典序定义为按行优先、行内从左到右的顺序比较。",
          "formal": "输出行 i 必须满足 a_{i,1} ≤ a_{i,2} ≤ ... ≤ a_{i,n}。",
          "source_sections": ["description"]
        },
        {
          "name": "optimality_and_lexicographic_min",
          "description": "输出方案必须使得所有合法排列中的最小中位数尽可能大，并且在所有达到该最大值的方案中，按上述规范顺序的字典序最小。",
          "formal": "令 goodness(A) = min_i median(row_i)。输出方案的质量 goodness 必须最大化，且在所有最大化 good 的方案中，其整矩阵序列字典序最小。",
          "source_sections": ["objective"]
        }
      ]
    },
    "objective": {
      "type": "construct_canonical_witness",
      "description": "输出一个 n × n 矩阵，代表对原矩阵每行重排后的结果。要求：1) 满足代价约束和排列合法性；2) 最小中位数（goodness）最大化；3) 在所有达成最大 good 的方案中，按照每行内升序、行优先比较的字典序最小。",
      "target": "canonical_solution",
      "requires_solution": true
    },
    "invariant": {
      "invariants": [
        {
          "name": "decision_monotonicity",
          "description": "对于阈值 X，能否在代价 ≤ k 的条件下使每行中位数 ≥ X 的可行性关于 X 单调非增。该性质保证二分搜索正确，并且原可行性检查过程不受输出规范影响。",
          "properties": {},
          "evidence_source": "inherited_from_seed"
        },
        {
          "name": "suffix_feasibility_bounded",
          "description": "在逐行贪心构造字典序最小解的过程中，当固定前 i-1 行的选择后，剩余行的最小可能代价（基于原贪心计算）能够被预先计算。如果当前已用代价加上后缀最小代价 > k，则不可能完成构造。这一不变式保证剪枝的正确性。",
          "properties": {},
          "evidence_source": "new_proof"
        },
        {
          "name": "greedy_lexicographic_progress",
          "description": "对于当前行 i，在所有满足局部字典序最小且可扩展（即后缀可行性成立）的候选中，选择最小的行序列不会丢失全局字典序最小解。这是因为若两个候选的行序列前缀不同，字典序更小的若可扩展，则更优；若字典序相同，则可任选。需要证明可扩展性测试是充分的。",
          "properties": {},
          "evidence_source": "new_proof"
        }
      ]
    },
    "difficulty": "medium_hard"
  },
  "algorithmic_delta_claim": {
    "seed_solver_core": "二分答案 + 贪心可行性检查：对于阈值 X，对每一行贪心选择最小的中位数（在保证该行至少 ⌈n/2⌉ 个元素 ≥ X 的前提下），计算总代价，检查是否 ≤ k。",
    "reusable_subroutines": "阈值 X 下的单行最小代价计算（给定行和 X，在升序排列中找最小的满足中位数 ≥ X 的代价），可用于计算后缀最小代价总和。",
    "new_solver_core": "先二分得到最优 goodness 值 G。然后从第一行开始，逐行枚举该行所有可能的、符合规范顺序（升序）且中位数 ≥ G 的排列子集。对每个候选，使用后缀最小代价判断是否仍可能满足总代价限制。在第一组可行的候选行中选择字典序最小的整行序列；若不可行则取消上一行选择并回溯，但利用强大的剪枝可以避免状态爆炸。最终构造出字典序最小的完整方案。",
    "new_proof_obligation": "需要证明：1) 在最优 G 下，逐行贪心选择过程中，仅凭后缀最小代价剪枝不会错过字典序更小的方案；2) 规范升序排列下，行内字典序比较与整行选择的最小性是一致的（即不存在通过非升序排列获得更小整矩阵字典序的可能性）；3) 贪心过程不会陷入需要回溯的状态，或者就算有回溯，其复杂度仍在可控范围内（需要具体分析）。",
    "why_direct_reuse_fails": "原解只输出一个数字，对具体排列的顺序完全没有要求；即使能记录出任意一个可行方案，也无法证明其字典序最小。要实现字典序最小的规范解，必须引入行内选择空间的排序与搜索，并在全局代价限制下进行前瞻剪枝，这不是原解顺手就能完成的。"
  },
  "anti_shallow_rationale": "新题不是简单地“在求出答案后任意输出一种方案”。它明确要求输出的排列必须是所有最优解中规范顺序字典序最小的，这迫使算法不仅要知道可行域，还要对解空间进行字典序排序并证明选取的正确性。原题的核心贪心仅关心代价的最小化，而新题要在字典序的意义下重新平衡每行的选择，导致状态设计和正确性证明彻底翻新，避免了表面换皮。",
  "applied_helpers": [
    {
      "id": "canonical_order_pressure",
