请审查该规划是否兑现规则专属合同。
要求：
- `message` 直接概括结论，不要泛泛而谈。
- `errors` 只写真正构成拒绝的规则专属问题；通过时返回空数组。
- `evidence` 必须引用给定 payload、schema 或规则声明中的具体内容。
- 如果规则声明了 `helpers`，要逐条核对 helper 是否全部出现，以及每个 helper 是否兑现了自己的目标变化轴、落点和 redlines。
- 如果不能确认已经兑现规则专属合同，返回 `fail`。

{
  "review_type": "rule_plan_validation",
  "mode": "single_seed_extension",
  "review_role": "你扮演一名规范解规划审查官，重点确认规划是否真正把输出责任升级为可比较、可校验的规范解。",
  "review_brief": "确认规划是否明确了规范解的定义、比较口径与校验方式，并且规范性会改变主要求解责任。",
  "rule_under_review": {
    "id": "canonical_witness",
    "family": "output_upgrade",
    "summary": "把原题改成需要输出并校验一个规范解的新题。",
    "audit_tags": [
      "single_seed",
      "witness",
      "output_contract"
    ],
    "required_axis_changes": {
      "must_change": [
        "C",
        "O",
        "V"
      ]
    },
    "core_transformation": {
      "primary_operator": "canonical_witness",
      "target_shift": "从给答案改成给规范解",
      "new_obligation": "输出一个可以直接检查的规范方案"
    },
    "helpers": [
      {
        "id": "canonical_order_pressure",
        "summary": "把规范顺序推进到主状态演化。",
        "must_realize_in": [
          "core_constraints",
          "objective",
          "invariant"
        ],
        "target_axes": [
          "C",
          "O",
          "V"
        ],
        "innovation_role": "让输出对象与验证责任离开原题路径。",
